    if (!A || !B) { out.innerHTML = '<div class="pnote">Choose two runs.</div>'; return; } if (A === B) { D.note('Cst', 'A and B are the same run: choose another one as B.', 1); }
    const o = opt(), keys = Object.keys(A.logs).filter(k => B.logs[k]).sort(), res = keys.map(k => ({ k, R: cmp2(A.logs[k], B.logs[k], o) })), onlyA = Object.keys(A.logs).filter(k => !B.logs[k]), onlyB = Object.keys(B.logs).filter(k => !A.logs[k]);
